arguments.command:
cd /app; cat > /tmp/cmp.py <<'EOF'
import pandas as pd, numpy as np, json, sys
f=pd.read_parquet(sys.argv[1]); f["as_of"]=pd.to_datetime(f["as_of"],utc=True)
for log in ["logs/live_2026-01_sample.jsonl","logs/shadow_2025-03-10_14_sample.jsonl"]:
    rows=[json.loads(l) for l in open(log)]
    L=pd.DataFrame([{"customer_id":r["customer_id"],"as_of":pd.Timestamp(r["as_of"]),**r["features"]} for r in rows])
    m=L.merge(f,on=["customer_id","as_of"],suffixes=("_live",""))
    print(log,len(L),len(m))
    for c in [c for c in f.columns if c not in("customer_id","as_of")]:
        a,b=m[c+"_live"],m[c]
        if a.dtype==object or b.dtype==object: bad=~((a==b)|(a.isna()&b.isna()))
        else: bad=~(np.isclose(a.astype(float),b.astype(float),rtol=1e-9,atol=1e-6)|(a.isna()&b.isna()))
        print(f"  {c}: {bad.sum()} mismatches")
        if bad.sum(): print(m.loc[bad,["customer_id","as_of",c+"_live",c]].head(3).to_string())
EOF
python /tmp/cmp.py /tmp/f.parquet

